/* Authenticated fieldwork: private server accounts and scoped sync; device drafts work offline. */
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDate=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const iso=()=>new Date().toISOString(), uid=()=>crypto.randomUUID(), nice=t=>t?new Date(t).toLocaleString('en-GB',{dateStyle:'short',timeStyle:'short'}):'Never';
let db,state,session=null,view='overview',filterZone='All zones',filterType='All types',search='',formRecord=null,step=0,drawer=null,watch=null,saveTimer;
const zones=['North-East','North-West','South-West'];
const badge=s=>`<span class="badge ${s==='Returned'||s==='Draft'?'warn':s==='Rejected'?'red':s==='Submitted'?'blue':''}">${esc(s)}</span>`;
const icon={overview:'▦',collect:'▤',review:'✓',team:'♧',journey:'⌖',insights:'◷',sync:'⇅',design:'◇'};
function toast(s){$('#toast').textContent=window.fieldworkI18n.text(s);$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}
function event(kind,recordId,detail){state.audit.unshift({id:uid(),at:iso(),actor:session?.name||'Prototype',kind,recordId,detail})}
async function persist(){return new Promise((resolve,reject)=>{let t=db.transaction('state','readwrite');t.objectStore('state').put(state,'app');t.oncomplete=resolve;t.onerror=()=>{toast('Storage failed. Export a backup before closing.');reject(t.error)}})}
async function init(){
 const identity=await fieldworkAuth.bootstrap();
 if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
 if(!identity.account||identity.account.mustChangePassword){session=null;state={records:[],audit:[],logins:[],points:[]};render();return;}
 if(db)db.close();const account=identity.account,roster=identity.roster||[account];ROSTER=roster.map(a=>fieldworkAuth.profile(a,roster));
 session={name:account.name,role:account.role==='leadership'?'Leadership':account.role==='supervisor'?'Supervisor':'Enumerator',sourceRole:account.role,zone:account.zone,userId:account.id,uiLanguage:fieldworkI18n.language,locationConsent:fieldworkAuth.locationRequested,offline:identity.offline===true};
 db=await new Promise((resolve,reject)=>{const r=indexedDB.open('agrivah-fieldwork-user-'+account.id,1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
 state=await new Promise(resolve=>{const r=db.transaction('state').objectStore('state').get('app');r.onsuccess=()=>resolve(r.result)});
 if(!state)state={records:[],audit:[],logins:[],points:[],journey:false};
 state.logins=identity.logins||state.logins||[];
 if(!identity.offline){try{await pullFieldworkRecords()}catch(e){toast(e.message)}}
 state.records.forEach(r=>{if(!r.serverConflict)r.syncError=null});await persist();view=session.role==='Leadership'?'insights':session.role==='Supervisor'?'review':'overview';filterZone='All zones';filterType='All types';search='';render();fieldworkAuth.sync();
 if(session.locationConsent){await getLocation('login');fieldworkAuth.locationRequested=false;}
}
async function pullFieldworkRecords(){
 const data=await fieldworkAuth.records(),remote=data.records||[],old=new Map(state.records.map(r=>[r.id,r]));
 const local=state.records.filter(r=>r.user===session.userId&&!r.demo&&(r.pendingSync||!r.serverVersion));
 const merged=new Map(local.map(r=>[r.id,r]));
 for(const server of remote){const own=old.get(server.id);if(own?.pendingSync){
  if(own.status===server.status&&fieldworkAuth.equal(own.answers,server.answers)){merged.set(server.id,{...server,pendingSync:false});continue;}
  if(server.serverVersion===own.serverVersion){merged.set(server.id,own);continue;}
  if(own.status==='Draft'||own.status==='Returned'){own.syncError='A newer server version exists. Your local copy is retained.';own.serverConflict=server;merged.set(own.id,own);continue;}
 }merged.set(server.id,{...server,pendingSync:false});}
 state.records=[...merged.values()];
}
window.fieldworkShouldRetry=()=>!!session&&navigator.onLine&&state.records.some(r=>r.user===session.userId&&r.pendingSync&&!r.syncError&&!r.serverConflict);
window.fieldworkSync=async()=>{
 if(!session)return;const actorId=session.userId;let changed=false;
 for(const record of state.records.filter(r=>r.user===session.userId&&r.pendingSync&&!r.demo&&!r.serverConflict)){
  const snapshot=JSON.parse(JSON.stringify(record));
  try{const response=await fieldworkAuth.save(snapshot),server=response.record;if(session?.userId!==actorId)return;const current=state.records.find(r=>r.id===record.id);if(!current)continue;
   if(current.status===snapshot.status&&fieldworkAuth.equal(current.answers,snapshot.answers)){Object.assign(current,server,{pendingSync:false,syncError:null});}else{current.serverVersion=server.serverVersion;current.pendingSync=true;}
   changed=true;
  }catch(e){record.syncError=e.message;changed=true;if(['unauthorized','offline','password_change_required'].includes(e.code))break;}
 }
 if(session?.userId!==actorId||!db)return;if(changed)await persist();
 if(['review','insights','team'].includes(view))try{await pullFieldworkRecords();await persist()}catch{}
 if(!formRecord&&session)render();
};

function user(){return ROSTER.find(u=>u.id===session?.userId)}
function scoped(){return state.records.filter(r=>session.role==='Enumerator'?r.user===session.userId:session.role==='Supervisor'?r.zone===session.zone:true)}
function filtered(){return scoped().filter(r=>(filterZone==='All zones'||r.zone===filterZone)&&(filterType==='All types'||r.type===filterType)&&(!search||[r.id,r.answers.name,r.answers.ent1,r.answers.ward,r.lga,ROSTER.find(u=>u.id===r.user)?.name].join(' ').toLowerCase().includes(search.toLowerCase())))}
function login(){const change=fieldworkAuth.current?.mustChangePassword;return `<div class="login"><section class="login-story"><div class="brand"><span class="mark">❧</span> agrighar</div><div><div class="eyebrow">Jigawa livelihood study</div><h1>Better field data.<br>Stronger livelihoods.</h1><p>Secure access for the Jigawa field team and authorised leadership.</p><div class="row wrap"><span class="badge">27 LGAs</span><span class="badge">4 survey types</span><span class="badge">English · Hausa · Fulfulde</span></div></div><p class="small">Agrivah · JAIP fieldwork</p></section><section class="login-form"><div class="eyebrow">${change?'First sign-in':'Welcome to the fieldwork workspace'}</div><h1>${change?'Set your own password.':'Sign in to your workspace.'}</h1><p class="muted">${change?'Replace the initial password before accessing your assigned work.':'Use your phone number or assigned 10-digit login ID.'}</p><form id="login-form">${change?`<label for="auth-new-password">New password</label><input id="auth-new-password" name="password" type="password" autocomplete="new-password" minlength="12" maxlength="72" required><label for="auth-confirm-password">Confirm new password</label><input id="auth-confirm-password" name="confirmation" type="password" autocomplete="new-password" minlength="12" maxlength="72" required><p class="small muted">Use 12–72 characters including uppercase, lowercase, a number and a symbol. Do not reuse the initial password.</p>`:`<label for="auth-user-id">Login ID (phone number)</label><input id="auth-user-id" name="userId" type="tel" inputmode="tel" autocomplete="username" placeholder="10-digit ID or Nigerian phone number" required><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" autocomplete="current-password" maxlength="72" required><label class="row small"><input id="auth-location" name="location" type="checkbox" style="width:auto;margin:0"> Capture this device’s login location</label><p class="small muted">Location is collected only with your permission. First sign-in needs an internet connection.</p>`}<div id="auth-error" class="error" role="alert"></div><button id="auth-submit" class="primary" type="submit">${change?'Save new password':'Sign in'}</button></form>${change?'<button id="auth-cancel" class="quiet small" style="margin-top:15px">Cancel and sign out</button>':'<p class="small muted">Your role and assigned locations are set by the programme coordinator. Contact the coordinator if you cannot sign in.</p>'}<p class="small muted">Leadership access is restricted to authorised accounts. Passwords are never stored in this browser.</p><p><a class="download" href="/">← Back to Agrivah</a></p></section></div>`}

function render(){if(session&&view==='insights'&&session.role!=='Leadership')view='overview';if(!session){$('#app').innerHTML=login();bindLogin();window.fieldworkI18n.apply();return}const nav=[['overview','Overview'],...(session.role==='Enumerator'?[['collect','My surveys']]:[['review','Review queue'],['team','Team & user master']]),['journey','Location & activity'],...(session.role==='Leadership'?[['insights','Leadership analytics']]:[]),['sync','Offline & sync'],['design','Design & launch plan']];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="mark">❧</span> agrighar</div><div class="project"><div class="eyebrow">Current programme</div><strong>Jigawa livelihood study</strong><br><span class="muted">Nigeria · JAIP</span></div><nav class="nav">${nav.map(([v,l])=>`<button data-nav="${v}" class="${v===view?'active':''}"><span class="ico">${icon[v]}</span>${l}</button>`).join('')}</nav><div class="sidebar-bottom"><span class="badge"><i class="dot"></i> Authenticated workspace</span><p>Built around field realities.<br>Drafts save on this device; server receipts confirm shared records.</p></div></aside><div><header class="topbar"><span class="muted">Workspace <span style="margin:0 9px">/</span> <strong>${esc(nav.find(n=>n[0]===view)?.[1]||'Survey')}</strong></span><div class="topbar-right"><span class="badge ${navigator.onLine?'':'warn'}"><i class="dot"></i> ${navigator.onLine?'Device online':'Device offline'}</span><span class="avatar">${session.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><span class="user-name small">${esc(session.name)}<br><span class="muted">${session.role}</span></span><button id="logout" class="quiet small">Exit</button></div></header><main class="content">${formRecord?survey():({overview,collect,review,team,journey,insights,sync,design}[view]||overview)()}</main></div></div>${drawer?drawRecord():''}`;bind();if(view==='insights'&&!formRecord&&session.role==='Leadership'&&fieldworkAuth.current?.role==='leadership')bindLeadership();window.fieldworkI18n.apply();}
function head(k,title,sub,actions=''){return `<div class="page-head row between wrap"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="muted">${sub}</p></div><div class="row">${actions}</div></div>`}
function stats(items){return `<div class="stats">${items.map(([name,value,foot],i)=>`<div class="stat ${i===0?'accent':''}"><span class="${i===0?'':'muted'} small">${name}</span><div class="number">${value}</div><div class="foot">${foot}</div></div>`).join('')}</div>`}
function controls(){return `<div class="filters"><input id="search" type="search" placeholder="Search records, wards or team…" value="${esc(search)}" aria-label="Search records">${session.role==='Leadership'?`<select id="zone-filter" aria-label="Filter zone">${['All zones',...zones].map(z=>`<option ${z===filterZone?'selected':''}>${z}</option>`).join('')}</select>`:''}<select id="type-filter" aria-label="Filter survey">${['All types','HH','FGD','KII','ENT'].map(t=>`<option ${t===filterType?'selected':''} value="${t}">${FORM_NAMES[t]||t}</option>`).join('')}</select></div>`}
function table(records,editable=false){if(!records.length)return '<div class="empty">No records match this view.</div>';return `<div class="table-wrap"><table><thead><tr><th>Survey / record</th><th>Enumerator</th><th>Location</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody>${records.map(r=>`<tr><td><strong>${esc(r.id)}</strong><span class="muted">${FORM_NAMES[r.type]}${r.demo?' · Demo':''}</span></td><td>${esc(ROSTER.find(u=>u.id===r.user)?.name)}</td><td><strong>${esc(r.lga)}</strong><span class="muted">${esc(r.type==='ENT'?(r.answers.ent1||r.answers.ward||'Enterprise pending'):(r.answers.ward||'Ward pending'))}</span></td><td>${badge(r.status)}<div class="small muted">${r.pendingSync?'Waiting for server':r.serverVersion?'Server received':''}</div></td><td class="muted">${nice(r.updated)}</td><td><button data-open="${r.id}" class="small">${editable&&['Draft','Returned'].includes(r.status)?'Continue':'View'} →</button></td></tr>`).join('')}</tbody></table></div>`}
function overview(){const r=filtered(),approved=r.filter(x=>x.status==='Approved'),pending=r.filter(x=>x.status==='Submitted'),returned=r.filter(x=>x.status==='Returned');const byType=['HH','FGD','KII','ENT'].map(t=>[FORM_NAMES[t],r.filter(x=>x.type===t).length]);return head('Field operations','A clearer view of the field.','Jigawa livelihood study · Collection, quality and people in one place.',session.role==='Enumerator'?'<button class="primary" data-nav="collect">＋ New survey</button>':'<button id="export-records">↓ Export records</button>')+`<div class="notice">Authenticated workspace · ${r.filter(x=>x.serverVersion&&!x.pendingSync).length} server-received records in this view. Unsynced drafts stay on their collector’s device.</div>`+controls()+stats([['Records collected',r.length,'All statuses · current filters'],['Approved',approved.length,'Eligible for leadership insights'],['Awaiting review',pending.length,'Submitted records'],['Correction required',returned.length,'Returned to enumerators']])+`<div class="grid2"><section class="card"><div class="card-head"><div><h2>Collection by survey type</h2><span class="small muted">Record counts · ${filterZone}</span></div><span class="badge">${r.length} total</span></div>${byType.map(([t,n])=>`<div class="bar-row"><span>${t}</span><div class="bar"><div class="fill" style="width:${r.length?n/r.length*100:0}%"></div></div><strong>${n}</strong></div>`).join('')}<div class="legend"><span><i></i>Collected records, including samples</span><span>No collection targets set</span></div></section><section class="card"><h2>Needs your attention</h2><p class="small muted">Turn field signals into next steps.</p><div class="action-item"><span class="action-icon">✓</span><div><strong>${pending.length} records awaiting review</strong><p>Check completeness and source evidence.</p></div><button data-nav="${session.role==='Enumerator'?'collect':'review'}">Open</button></div><div class="action-item"><span class="action-icon">♧</span><div><strong>Resolve staffing gaps</strong><p>The updated roster has 28 enumerators; check the assignment register for current coverage.</p></div>${session.role!=='Enumerator'?'<button data-nav="team">View</button>':''}</div><div class="action-item"><span class="action-icon">⌖</span><div><strong>${r.filter(x=>!x.location).length} records without a location fix</strong><p>Review exceptions before approval.</p></div><button data-nav="journey">View</button></div></section></div><section class="card"><div class="card-head"><div><h2>Recent field submissions</h2><span class="small muted">Latest activity in your assigned scope</span></div><button data-nav="${session.role==='Enumerator'?'collect':'review'}" class="quiet small">View all →</button></div>${table([...r].sort((a,b)=>b.updated.localeCompare(a.updated)).slice(0,5),session.role==='Enumerator')}</section>`}
function collect(){return head('Enumerator workspace','Your next conversation starts here.','Choose a survey. Save at any point and continue on this device.')+`<div class="notice"><label for="collection-lga">Assigned LGA for the next survey</label> <select id="collection-lga">${(user().lgas||[user().lga]).map(l=>`<option value="${esc(l)}">${esc(l)}</option>`).join('')}</select></div><div class="two" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr));margin-bottom:24px">${Object.entries(FORM_NAMES).map(([t,n])=>`<section class="card"><div class="eyebrow">${t} · source-adapted preview</div><h2 style="margin-top:13px">${n}</h2><p class="muted small">${FORMS[t].length} guided sections · automatic local save<br>Assigned LGA: ${esc(user().lga)}</p><button data-new="${t}" class="primary">Start survey →</button></section>`).join('')}</div>`+controls()+`<section class="card"><h2>Your surveys</h2>${table(filtered(),true)}</section>`}
function visible(f,a){if(f.showIn&&!f.showIn[1].includes(a[f.showIn[0]]))return false;return !f.show||(Array.isArray(a[f.show[0]])?a[f.show[0]].includes(f.show[1]):a[f.show[0]]===f.show[1])}
function fieldHTML(f,a){const v=a[f.id]??'',attr=`data-field="${f.id}"`,label=`${esc(f.label)} ${f.required?'<span style="color:#a46c3b">*</span>':'<span class="muted">(optional)</span>'}`;let h;if(f.type==='fixedMatrix')h=f.fixedRows.map(row=>`<label class="row between" style="font-weight:400">${esc(row)}<select data-matrix="${f.id}" data-row="${esc(row)}" style="width:58%"><option value="">Choose a band</option>${f.options.map(o=>`<option ${v[row]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`).join('');else if(f.type==='multi')h=`<div class="chips">${f.options.map(o=>`<button type="button" class="chip ${(Array.isArray(v)&&v.includes(o))?'selected':''}" data-chip="${f.id}" data-value="${esc(o)}" aria-pressed="${Array.isArray(v)&&v.includes(o)}">${esc(o)}</button>`).join('')}</div>`;else if(f.type==='select')h=`<select id="f-${f.id}" ${attr}><option value="">Choose an answer</option>${f.options.map(o=>`<option ${o===v?'selected':''}>${esc(o)}</option>`).join('')}</select>`;else if(f.type==='textarea')h=`<textarea id="f-${f.id}" ${attr}>${esc(v)}</textarea>`;else if(f.type==='matrix'||f.type==='fixedMatrix'){const rows=(f.fixedRows||a[f.rows]||[]).filter(x=>x!=='Not Applicable');h=rows.length?rows.map(row=>`<label class="row between" style="font-weight:400">${esc(row)}<select data-matrix="${f.id}" data-row="${esc(row)}" style="width:60%"><option value="">Choose a band</option>${f.options.map(o=>`<option ${v[row]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`).join(''):'<p class="small muted">Select commodities above to display one card per commodity.</p>'}else h=`<input id="f-${f.id}" ${attr} type="${f.type}" value="${esc(v)}" ${f.min!==undefined?`min="${f.min}"`:''} ${f.max!==undefined?`max="${f.max}"`:''} ${f.type==='number'?'step="any"':''}>`;return `<div class="field ${['multi','textarea','matrix','fixedMatrix'].includes(f.type)?'full':''}"><label for="f-${f.id}">${label}</label>${f.help?`<p class="small muted">${esc(f.help)}</p>`:''}${h}${f.sourcePage?`<p class="small muted">Enterprise Q${f.number} · PDF p${f.sourcePage}${f.cardinalityAdapted?' · adapted to one answer':''}</p>`:''}</div>`}
function survey(){const sections=FORMS[formRecord.type],s=sections[step],a=formRecord.answers;return head(`${formRecord.type} / ${esc(formRecord.id)}`,FORM_NAMES[formRecord.type],`${esc(formRecord.lga)} · ${esc(session.name)}`,'<button id="close-survey">Save & close</button>')+`<div class="notice warn">Source-adapted design preview. Group discussion prompts are consolidated; the complete extracted source question catalog is in Design & launch plan. Final question wording, matrices and skip rules need survey-owner sign-off.</div>${formRecord.type==='ENT'?'<div class="notice warn">Enterprise question translations are drafts. Some new answer choices and technical dashboard notes remain in English pending native-speaker review.</div>':''}<div class="step-layout"><aside class="steps">${sections.map((s,i)=>`<button data-step="${i}" class="${i===step?'active':''}"><span>${i+1}</span>${s.title}</button>`).join('')}<button data-step="${sections.length}" class="${step===sections.length?'active':''}"><span>✓</span>Review & submit</button></aside><section class="card"><div class="row between"><span class="eyebrow">${step===sections.length?'Final check':`Section ${step+1} of ${sections.length}`}</span>${badge(formRecord.status)}</div><div class="progress"><div style="width:${step/sections.length*100}%"></div></div>${s?`<h2>${s.title}</h2>${s.note?`<p class="small muted">${esc(s.note)}</p>`:''}<div class="form-grid" style="margin-top:25px">${s.fields.filter(f=>visible(f,a)).map(f=>fieldHTML(f,a)).join('')}</div>`:`<h2>Ready for supervisor review?</h2><p class="muted">Check missing fields before submitting. Submission locks editing until a supervisor returns the record.</p><div id="validation">${validationSummary()}</div><div class="notice">${formRecord.location?`Last fix: ${formRecord.location.lat.toFixed(5)}, ${formRecord.location.lng.toFixed(5)} · ±${Math.round(formRecord.location.accuracy)} m`:'No location fix. Add a reason in Visit & consent before submitting.'}</div>${formRecord.reviewNote?`<div class="notice warn">Supervisor note: <span data-user-content>${esc(formRecord.reviewNote)}</span></div>`:''}`}<div id="form-error" class="error" role="alert"></div><div class="form-foot"><button id="prev-step" ${step===0?'disabled':''}>← Back</button><span id="save-status" class="small muted">Saved on this device · ${nice(formRecord.updated)}</span>${s?'<button id="next-step" class="primary">Continue →</button>':'<button id="submit-record" class="primary">Submit for review →</button>'}</div></section></div>`}
function errors(){const a=formRecord.answers,e=[];for(const [i,s]of FORMS[formRecord.type].entries())for(const f of s.fields.filter(f=>visible(f,a))){let v=a[f.id];if(f.exclusiveOptions&&Array.isArray(v)&&v.length>1&&v.some(x=>f.exclusiveOptions.includes(x)))e.push({i,label:f.label+' — conflicting answers'});if(f.maxSelections&&Array.isArray(v)&&v.length>f.maxSelections)e.push({i,label:f.label+' — choose at most '+f.maxSelections});if(f.integer&&v!==undefined&&v!==''&&!Number.isInteger(Number(v)))e.push({i,label:f.label+' — enter a whole number'});if(f.type==='matrix'||f.type==='fixedMatrix'){const rows=(f.fixedRows||a[f.rows]||[]).filter(x=>x!=='Not Applicable');if(rows.some(row=>!v?.[row]))e.push({i,label:f.label})}else if(f.required&&(v===undefined||v===''||Array.isArray(v)&&!v.length))e.push({i,label:f.label});else if(f.type==='number'&&v!==''&&v!==undefined&&(!Number.isFinite(Number(v))||f.min!==undefined&&Number(v)<f.min||f.max!==undefined&&Number(v)>f.max))e.push({i,label:f.label+' — outside allowed range'})}if(a.consent!=='Yes')e.push({i:0,label:'Participation consent required. If refused, close as non-participation in production.'});if(!formRecord.location&&!a.locationReason?.trim())e.push({i:0,label:'Location exception reason required'});return e}
function validationSummary(){let e=errors();return e.length?`<div class="notice warn">${e.length} fields need attention.</div>${e.slice(0,12).map(x=>`<p><button class="quiet small" data-step="${x.i}">${esc(x.label)} →</button></p>`).join('')}`:'<div class="notice">All required preview fields are complete.</div>'}
function review(){const r=filtered();return head('Quality control','Review with confidence.','Your queue contains records from your assigned scope. Every decision keeps its history.')+controls()+`<div class="tabs">${['Submitted','Returned','Approved','Rejected','All'].map(t=>`<button data-reviewtab="${t}" class="${(window.reviewTab||'Submitted')===t?'active':''}">${t} ${t==='All'?r.length:r.filter(x=>x.status===t).length}</button>`).join('')}</div><section class="card">${table(r.filter(x=>(window.reviewTab||'Submitted')==='All'||x.status===(window.reviewTab||'Submitted')))}</section>`}
function team(){const people=ROSTER.filter(u=>filterZone==='All zones'||u.zone===filterZone),active=ROSTER.filter(u=>u.lastActivityAt&&Date.now()-new Date(u.lastActivityAt).getTime()<300000).length;return head('People & assignments','User master','Account roles and assignments come from the private server registry.','<button id="refresh-master">Refresh status</button><button id="export-master">↓ Export master sheet</button>')+stats([['Visible accounts',ROSTER.length,'Scoped to your authorised team'],['Leadership accounts',ROSTER.filter(u=>u.role==='leadership').length,'Only the five named leadership users'],['Recently active',active,'Server session activity within 5 minutes'],['First sign-ins',ROSTER.filter(u=>u.firstLoginAt).length,'Successful credential verification']])+controls()+`<section class="card"><div class="card-head"><h2>Accounts & assignments</h2><span class="small muted">Passwords are never displayed or exported</span></div><div class="table-wrap"><table><thead><tr><th>User / role</th><th>Login ID</th><th>Division / LGAs</th><th>Supervisor</th><th>First login</th><th>Last activity</th></tr></thead><tbody>${people.filter(u=>!search||[u.name,...u.lgas].join(' ').toLowerCase().includes(search.toLowerCase())).map(u=>`<tr><td><strong>${esc(u.name)}</strong><span class="muted">${esc(u.role)}</span></td><td>${esc(u.phone)}</td><td><strong>${esc(u.zone||'Programme-wide')}</strong><span class="muted">${esc(u.lgas.join(', '))}</span></td><td>${esc(u.supervisor)}</td><td>${nice(u.firstLoginAt)}</td><td>${nice(u.lastActivityAt||u.lastLoginAt)}</td></tr>`).join('')}</tbody></table></div></section><section class="card" style="margin-top:20px"><h2>Login register</h2><p class="small muted">Recent activity is a server timestamp, not proof of continuous presence. First-login location is recorded only after permission is granted.</p>${state.logins.slice(0,50).map(l=>`<div class="action-item"><div><strong>${esc(l.name)}</strong><p>${esc(l.role)} · ${nice(l.at)}</p></div></div>`).join('')||'<div class="empty">No login events in this scope.</div>'}</section>`}

function points(){return state.points.filter(p=>session.role==='Leadership'||session.role==='Supervisor'&&p.zone===session.zone||p.userId===session.userId)}
function distance(ps){let km=0;for(let i=1;i<ps.length;i++){const a=ps[i-1],b=ps[i];if(a.shiftId!==b.shiftId||a.userId!==b.userId||a.accuracy>50||b.accuracy>50)continue;const rad=x=>x*Math.PI/180,dlat=rad(b.lat-a.lat),dlon=rad(b.lng-a.lng),h=Math.sin(dlat/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dlon/2)**2;const m=6371000*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h)),dt=(new Date(b.at)-new Date(a.at))/1000;if(dt>0&&dt<300&&m>Math.max(a.accuracy,b.accuracy)&&m/dt<45)km+=m/1000}return km}
function journey(){let p=points(),shiftPoints=p.filter(x=>x.kind==='track');return head('Location intelligence','Every visit, with context.','Login and survey-event locations · foreground shift tracking by choice.',`<button id="capture-location">⌖ Capture location</button>${session.role==='Enumerator'?`<button id="toggle-shift" class="primary">${watch!==null?'Stop shift':'Start shift'}</button>`:''}`)+stats([['Sampled distance',distance(shiftPoints).toFixed(2)+' km','Filtered point-to-point estimate'],['Location events',p.length,'Actual fixes on this browser'],['Low accuracy',p.filter(x=>x.accuracy>50).length,'Above proposed 50 m threshold'],['Tracking',watch!==null?'On':'Off','Foreground only · this device']])+`<div class="grid2"><section class="card"><h2>Location evidence</h2><p class="small muted">An accurate fix is better than an invented route.</p><div class="journey-map"><div><strong>⌖ ${p.length?'Captured points available below':'No location points captured yet'}</strong><p class="small muted">Schematic background · not a geographic map.<br>No route is drawn across gaps or missing fixes.</p></div></div></section><section class="card"><h2>Designed for patchy connectivity</h2><p class="small muted">GPS can provide outdoor fixes without mobile data. Android’s fused location service can combine available GPS, Wi-Fi and cellular signals. Network positioning is conditional; it cannot be guaranteed when offline.</p><div class="rule"></div><h3>Capture policy</h3><p class="small muted">Record login, visit start, section save and submission. Store coordinates, event time and accuracy. Keep a reason when permission is denied or a fix times out.</p><h3>Travel is an estimate</h3><p class="small muted">Distance excludes fixes above 50 m accuracy, obvious jumps, jitter and gaps over 5 minutes. This browser preview stops tracking at exit; native Android is needed for reliable shift tracking.</p></section></div><section class="card"><h2>Captured event log</h2>${p.length?`<div class="table-wrap"><table><thead><tr><th>Event</th><th>Time</th><th>Coordinates</th><th>Accuracy</th><th>User</th></tr></thead><tbody>${[...p].reverse().slice(0,50).map(x=>`<tr><td>${esc(x.kind)}</td><td>${nice(x.at)}</td><td>${x.lat.toFixed(5)}, ${x.lng.toFixed(5)}</td><td>${Math.round(x.accuracy)} m</td><td>${esc(x.name)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Allow location and capture a fix to see evidence here.</div>'}</section>`}
function legacyInsights(){const r=filtered().filter(r=>r.status==='Approved'),hh=r.filter(r=>r.type==='HH'),withSupport=hh.filter(r=>Array.isArray(r.answers.support)&&r.answers.support.length),loss=hh.filter(r=>r.answers.loss!==undefined&&r.answers.loss!==''&&Number.isFinite(Number(r.answers.loss))),mean=loss.length?loss.reduce((s,r)=>s+Number(r.answers.loss),0)/loss.length:null;return head('Leadership intelligence','From field evidence to action.','Approved records only · Household responses and qualitative interviews remain separate.')+`<div class="notice warn">Illustrative insights from demonstration and locally approved preview records. These are not representative estimates for Jigawa. No inference is made from unreviewed data.</div>`+controls()+stats([['Approved records',r.length,'Current zone and survey filters'],['Household evidence',hh.length,'Households, not participants'],['Mean reported loss',mean===null?'—':mean.toFixed(1)+'%','Unweighted · '+loss.length+' non-missing HH responses'],['Support responses',withSupport.length,'Approved HH with needs recorded']])+`<div class="grid2"><section class="card"><h2>Where support is requested</h2><p class="small muted">Multi-select · approved HH base n=${withSupport.length}. Percentages may sum above 100%.</p>${support.filter(o=>o!=='Other').map(s=>{let n=withSupport.filter(r=>r.answers.support.includes(s)).length;return `<div class="bar-row"><span>${s}</span><div class="bar"><div class="fill" style="width:${withSupport.length?n/withSupport.length*100:0}%"></div></div><strong>${n}</strong></div>`}).join('')}</section><section class="card"><h2>Actionable follow-up</h2>${withSupport.length?`<div class="action-item"><span class="action-icon">↗</span><div><strong>Validate needs at LGA level</strong><p>Review households requesting finance, storage or market access. Check the denominator and geography before prioritising programmes.</p></div></div>`:'<p class="muted">Approve household records to generate support-needs evidence.</p>'}<div class="action-item"><span class="action-icon">◷</span><div><strong>Triangulate with group evidence</strong><p>${r.filter(x=>x.type==='FGD').length} approved FGD and ${r.filter(x=>x.type==='KII').length} approved KII records. Treat themes as qualitative evidence; do not count group members as households.</p></div></div><div class="action-item"><span class="action-icon">✓</span><div><strong>Keep uncertainty visible</strong><p>Survey targets, sampling weights and population denominators have not been supplied. Avoid state-level totals or impact claims.</p></div></div></section></div><section class="card"><div class="card-head"><h2>Evidence behind the view</h2><button id="export-approved" class="small">↓ Export approved</button></div>${table(r)}</section>`}
function sync(){const own=state.records.filter(r=>r.user===session.userId),pending=own.filter(r=>r.pendingSync);return head('Offline & server sync','Your records, with a server receipt.','Drafts save on this device. Online changes are checked against the latest server version.','<button id="sync-now" class="primary">Sync now</button><button id="refresh-records">Refresh server records</button>')+stats([['Your local records',own.length,'This authenticated device profile'],['Waiting for server',pending.length,'Not yet acknowledged'],['Server received',own.filter(r=>r.serverVersion&&!r.pendingSync).length,'Acknowledged version'],['Conflicts',own.filter(r=>r.serverConflict).length,'Local changes retained']])+`<div class="notice">First sign-in and password changes need an internet connection. Field collectors can resume this device’s drafts offline during the cached session period; leadership review requires online verification. Review decisions are saved only after a server response.</div><div class="grid2"><section class="card"><h2>Pending uploads</h2>${pending.length?pending.map(r=>`<div class="review-answer"><strong>${esc(r.id)}</strong><p class="small">${esc(FORM_NAMES[r.type])} · ${esc(r.status)}</p><p class="small muted">${esc(r.syncError||'Waiting to upload')}</p>${r.serverConflict?`<button class="small" data-use-server="${esc(r.id)}">Use server copy (discard local changes)</button>`:''}</div>`).join(''):'<div class="empty">No pending records.</div>'}<button id="backup">Download local backup</button></section><section class="card"><h2>How review works</h2><p>Draft → Submitted to server → Approved, Returned or Rejected.</p><p class="small muted">A record waiting on this device is not visible to your supervisor. Once the server acknowledges it, review uses the assigned supervisor account. Returned records retain the correction note and history. Conflicting changes are never silently overwritten.</p></section></div>`}

function design(){return head('Application blueprint','Designed for the field. Ready for review.','A practical rollout plan for Android enumerators and web-based oversight.','<a href="blueprint.md" class="download" download>↓ Download blueprint</a>')+`<div class="notice">Phone-ID sign-in, private accounts, server permissions, shared records and supervisor review are connected. Offline drafts remain on this device until the server acknowledges them. Native Android background tracking remains future work.</div><div class="two"><section class="card"><h2>Roles & access</h2><p><strong>Enumerator</strong> · Assigned visits, offline capture, draft/resume, correction and own activity.</p><p><strong>Supervisor</strong> · Assigned division, quality checks, approval, return with note, rejection, exception review and audit.</p><p><strong>Leadership</strong> · Programme oversight, login activity, coverage, review ageing, approved insights and exports.</p><p><strong>Administrator</strong> · Invite/disable users, reconcile assignments, version forms and manage scoped exports.</p><p class="small muted">Roles and assignments are checked by the server on every request. Leadership is restricted to the five authorised accounts.</p></section><section class="card"><h2>Launch decisions</h2><div class="action-item"><div><strong>01 · Reconcile staffing</strong><p>84 unique accounts are provisioned from the updated workbook, including community liaisons. Confirm assignments during the field pilot.</p></div></div><div class="action-item"><div><strong>02 · Approve survey dictionary</strong><p>Sign off every prompt, option, matrix, required field and skip rule. Fix participant-band gaps and inconsistent LGA spellings.</p></div></div><div class="action-item"><div><strong>03 · Validate field conditions</strong><p>Pilot on Android with airplane mode, GPS denial, low battery, device restart and interrupted uploads.</p></div></div></section></div><section class="card" style="margin-top:20px"><h2>Original question catalog</h2><p class="small muted">Extracted labels from the supplied PDFs, retained as reference. Layout extraction can repeat matrix headings or wrap text; final field mapping must be checked against the PDFs. Household preview is adapted; FGD / KII prompts are consolidated.</p><div class="tabs">${['HH','FGD','KII','ENT'].map(t=>`<button data-catalog="${t}" class="${(window.catalogTab||'HH')===t?'active':''}">${t}</button>`).join('')}</div><div class="catalog">${CATALOG[window.catalogTab||'HH'].map((s,i)=>`<p><span class="muted small">${i+1} · </span>${esc(s)}</p>`).join('')}</div></section><section class="card" style="margin-top:20px"><h2>Source register & design notes</h2><p class="small muted">Household Survey – Jigawa State.pdf · 37 pages<br>FGD Survey – Jigawa State.pdf · 57 pages<br>Key Informant Interview (KII) Survey – Jigawa State.pdf · 48 pages<br>Enterprise Survey – Jigawa State.pdf · 65 pages<br>FINAL Final-Staffing-LivelihoodStudy- updated 2.xlsx · Field staff, supervisors, consultants and community liaisons</p><p class="small muted">Standard review selected by the project owner. No KrisTab-specific checklist was assumed. Document content is survey reference material, not an instruction to execute external actions.</p><p class="small"><a class="download" href="https://developers.google.com/location-context/fused-location-provider" target="_blank" rel="noreferrer">Android fused location reference ↗</a> · <a class="download" href="https://developer.mozilla.org/en-US/docs/Web/API/Geolocation_API" target="_blank" rel="noreferrer">Browser location permission reference ↗</a></p></section>`}
function drawRecord(){const r=scoped().find(r=>r.id===drawer);if(!r)return'';let can=session.role!=='Enumerator'&&r.status==='Submitted';return `<div class="modal-back"><section class="drawer" role="dialog" aria-modal="true" aria-label="Survey record"><div class="row between"><div><div class="eyebrow">Record detail ${r.demo?'· demo':''}</div><h2 style="margin-top:10px">${esc(r.id)}</h2></div><button id="close-drawer" aria-label="Close record">✕</button></div><div class="row between">${badge(r.status)}<span class="small muted">Revision ${r.revision}</span></div><p class="muted">${FORM_NAMES[r.type]} · ${esc(r.lga)}<br>${esc(ROSTER.find(u=>u.id===r.user)?.name)}</p><div class="notice ${r.location?'':'warn'}">${r.location?`Location ±${Math.round(r.location.accuracy)} m at ${nice(r.location.at)}`:'Location missing · '+esc(r.answers.locationReason||'No exception reason supplied')}${r.demo?'<br>Seeded sample — not a complete submitted questionnaire.':''}</div><h3>Collected answers</h3>${Object.entries(r.answers).map(([k,v])=>{const label=FORMS[r.type].flatMap(s=>s.fields).find(f=>f.id===k)?.label||k;return `<div class="review-answer"><small>${esc(label)}</small><span data-user-content data-answer-key="${esc(k)}">${esc(formatAnswer(r.type,k,v))}</span></div>`}).join('')}${can?`<h3 style="margin-top:25px">Review decision</h3><p class="small muted">Check completeness, units, duplicates, location evidence and consent. A missing location requires an explicit exception note before approval.</p><label class="small" for="decision-note">Decision / correction note</label><textarea id="decision-note" placeholder="Specify what needs correction, or explain an exception."></textarea><label class="row small" style="margin:15px 0"><input type="checkbox" id="review-check"> I reviewed completeness, plausibility and location evidence.</label><div class="row wrap"><button data-decision="Approved" class="primary">Approve</button><button data-decision="Returned">Return for correction</button><button data-decision="Rejected" class="danger">Reject</button></div>`:''}<h3 style="margin-top:30px">Record history</h3>${r.history.map(h=>`<div class="audit"><strong>${esc(h.status)}</strong><p><span data-user-content>${esc(h.note||'')}</span></p><span class="muted">${nice(h.at)}</span></div>`).join('')}<h3>Audit events</h3>${state.audit.filter(a=>a.recordId===r.id).map(a=>`<div class="audit"><strong>${esc(a.kind)}</strong><p>${esc(a.actor)} · <span data-user-content>${esc(a.detail)}</span></p><span class="muted">${nice(a.at)}</span></div>`).join('')}</section></div>`}
function getLocation(kind,recordId){return new Promise(resolve=>{if(!navigator.geolocation){resolve(null);return}navigator.geolocation.getCurrentPosition(async p=>{const fix={lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy,at:new Date(p.timestamp).toISOString(),kind,recordId,userId:session?.userId,name:session?.name,zone:session?.zone,shiftId:session?.shiftId};state.points.push(fix);await persist();if(session&&kind==='login')try{await fieldworkAuth.request('location',{location:fix})}catch{}resolve(fix)},e=>{toast(e.code===1?'Location permission denied. Add an exception reason for a survey.':'No location fix available. You can continue collecting.');resolve(null)},{enableHighAccuracy:true,timeout:12000,maximumAge:0})})}
