async function saveRecord(capture=false){if(!formRecord)return;if(formRecord.status==='Returned'){formRecord.status='Draft';formRecord.revision++;formRecord.history.unshift({at:iso(),status:'Draft',note:'Correction started'})}formRecord.updated=iso();formRecord.pendingSync=true;await persist();clearTimeout(window.cloudSyncTimer);window.cloudSyncTimer=setTimeout(()=>fieldworkAuth.sync(),2000);if($('#save-status'))$('#save-status').textContent=window.fieldworkI18n.text('Saved on this device · '+nice(formRecord.updated));if(capture&&session.locationConsent){const target=formRecord;const fix=await getLocation('section save',target.id);if(fix){target.location=fix;await persist()}}}
function changeAnswer(id,value){formRecord.answers[id]=value;formRecord.pendingSync=true;if(!formRecord.serverConflict)formRecord.syncError=null;clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveRecord(),250)}
function download(name,data,type){let blob=new Blob([data],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function csv(rows){return rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')}
