function formatAnswer(type,key,value){const f=FORMS[type].flatMap(s=>s.fields).find(f=>f.id===key);const t=s=>window.fieldworkI18n.text(s);if(!f||!['multi','select','matrix','fixedMatrix'].includes(f.type))return typeof value==='object'?JSON.stringify(value):value;if(Array.isArray(value))return value.map(t).join(', ');if(value&&typeof value==='object')return Object.entries(value).map(([row,answer])=>t(row)+': '+t(answer)).join('; ');return t(value)}
